int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info) {
    struct hwsim_new_radio_params params = { .strict_reg = false,
                                             .support_p2p_device = false,
                                             .channels = 0,
                                             .regulatory_alpha2 = NULL,
                                             .name = NULL,
                                             .idx = -1 };

    if (info->attrs[HWSIM_ATTR_REG_STRICTNESS])
        params.strict_reg = true;

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE])
        params.support_p2p_device = true;

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        params.channels = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNELS]);
        if (params.channels == 0)
            return -EINVAL;
    }

    if (info->attrs[HWSIM_ATTR_REG_ALPHA2])
        params.regulatory_alpha2 = nla_data(info->attrs[HWSIM_ATTR_REG_ALPHA2]);

    if (info->attrs[HWSIM_ATTR_NAME]) {
        params.name = kstrdup(nla_data(info->attrs[HWSIM_ATTR_NAME]),
                              nla_len(info->attrs[HWSIM_ATTR_NAME]));
        if (!params.name)
            return -ENOMEM;
    }

    if (info->attrs[HWSIM_ATTR_IDX]) {
        params.idx = nla_get_u32(info->attrs[HWSIM_ATTR_IDX]);
        if (params.idx >= MAX_VIFS)
            return -EINVAL;
    }

    int result = mac80211_hwsim_new_radio(&params);

    kfree(params.name);
    return result;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info)
{
    struct hwsim_new_radio_params params = { 0 };
    int err;

    if (info->attrs[HWSIM_ATTR_REG_STRICTNESS]) {
        params.reg_strictness = nla_get_u8(info->attrs[HWSIM_ATTR_REG_STRICTNESS]);
        if (params.reg_strictness > MAC80211_HWSIM_REG_STRICTNESS_MAX)
            return -EINVAL;
    }

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE])
        params.support_p2p = true;

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        params.channels = nla_data(info->attrs[HWSIM_ATTR_CHANNELS]);
        params.n_channels = nla_len(info->attrs[HWSIM_ATTR_CHANNELS]) / sizeof(u32);
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        size_t len = nla_len(info->attrs[HWSIM_ATTR_RADIO_NAME]) + 1;
        params.radio_name = kstrndup(nla_data(info->attrs[HWSIM_ATTR_RADIO_NAME]),
                                     len, GFP_KERNEL);
        if (!params.radio_name)
            return -ENOMEM;
    }

    if (info->attrs[HWSIM_ATTR_CUSTOM_REG]) {
        params.regd_def = nla_data(info->attrs[HWSIM_ATTR_CUSTOM_REG]);
        if (params.regd_def >= mac80211_hwsim_regdoms)
            return -ERANGE;
    }

    err = mac80211_hwsim_new_radio(&params);
    if (err < 0)
        goto out;

out:
    kfree(params.radio_name);
    return err;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info)
{
    struct hwsim_new_radio_params params = { 0 };
    int ret = -EINVAL;

    if (info->attrs[HWSIM_ATTR_REG_STRICT_REG])
        params.reg_strict = true;

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE])
        params.support_p2p = true;

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        params.channels = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNELS]);
        if (params.channels <= 0)
            return -EINVAL;
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        params.name = kstrdup(nla_data(info->attrs[HWSIM_ATTR_RADIO_NAME]),
                              GFP_KERNEL);
        if (!params.name)
            return -ENOMEM;
    }

    if (info->attrs[HWSIM_ATTR_REGulatory_DOMAIN_IDX]) {
        params.domain_idx = nla_get_u32(info->attrs[HWSIM_ATTR_REGULATORY_DOMAIN_IDX]);
        if (params.domain_idx >= MAC80211_HWSIM_MAX_REG_DOMAINS) {
            ret = -ERANGE;
            goto out;
        }
    }

    ret = mac80211_hwsim_new_radio(&params);

out:
    if (params.name)
        kfree(params.name);
    return ret;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info) {
    struct hwsim_new_radio_params params = {0};
    int err;

    if (info->attrs[HWSIM_ATTR_REG_STRICTNESS]) {
        params.reg_strictness = nla_get_u8(info->attrs[HWSIM_ATTR_REG_STRICTNESS]);
    }

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE]) {
        params.support_p2p_device = !!nla_get_u8(info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE]);
    }

    if (info->attrs[HWSIM_ATTR_CHANNELS]) {
        params.channels = nla_data(info->attrs[HWSIM_ATTR_CHANNELS]);
        params.n_channels = nla_len(info->attrs[HWSIM_ATTR_CHANNELS]) / sizeof(u32);
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        params.name = kstrdup(nla_data(info->attrs[HWSIM_ATTR_RADIO_NAME]), GFP_KERNEL);
        if (!params.name) {
            return -ENOMEM;
        }
    }

    if (info->attrs[HWSIM_ATTR_REGD_IDX]) {
        params.regd_idx = nla_get_u32(info->attrs[HWSIM_ATTR_REGD_IDX]);
        if (params.regd_idx >= ARRAY_SIZE(hwsim_regdoms)) {
            err = -EINVAL;
            goto out_free_name;
        }
    }

    err = mac80211_hwsim_new_radio(&params);
    if (err < 0) {
        goto out_free_name;
    }

out_free_name:
    kfree(params.name);
    return err;
}

int hwsim_new_radio(struct sk_buff *msg, struct genl_info *info)
{
    struct hwsim_new_radio_params params = { };
    int err;

    if (info->attrs[HWSIM_ATTR_REG_STRICTNESS]) {
        params.reg_strictness = nla_get_u8(info->attrs[HWSIM_ATTR_REG_STRICTNESS]);
    }

    if (info->attrs[HWSIM_ATTR_SUPPORT_P2P_DEVICE])
        params.support_p2p_device = true;

    if (info->attrs[HWSIM_ATTR_CHANNEL]) {
        params.channel = nla_get_u32(info->attrs[HWSIM_ATTR_CHANNEL]);
    }

    if (info->attrs[HWSIM_ATTR_RADIO_NAME]) {
        params.name = kstrdup(nla_get_string(info->attrs[HWSIM_ATTR_RADIO_NAME]), GFP_KERNEL);
        if (!params.name) {
            return -ENOMEM;
        }
    }

    if (info->attrs[HWSIM_ATTR_REGULATORY_ALPHA2]) {
        nla_get_string(info->attrs[HWSIM_ATTR_REGULATORY_ALPHA2]);
    }

    if (info->attrs[HWSIM_ATTR_CUSTOM_REG_DOMAIN]) {
        params.regulatory_idx = nla_get_u32(info->attrs[HWSIM_ATTR_CUSTOM_REG_DOMAIN]);
        if (params.regulatory_idx >= MAX_CUSTOM_REGULATORY_DOMAINS) {
            kfree(params.name);
            return -EINVAL;
        }
    }

    err = mac80211_hwsim_new_radio(&params);
    if (err < 0) {
        kfree(params.name);
        return err;
    }

    return 0;
